SELECT * FROM chat_message
WHERE thread_id = #{threadId}
ORDER BY created_at ASC, message_id ASC


SELECT message.* FROM chat_message message JOIN (
    SELECT message_id, created_at FROM (
        SELECT message_id, created_at,
               ROW_NUMBER() OVER (PARTITION BY agent_id ORDER BY created_at DESC, message_id ASC) AS agent_rank
        FROM chat_message
        WHERE thread_id = #{threadId} AND role = 'ASSISTANT' AND status = 'COMPLETED'
          AND agent_id IS NOT NULL AND agent_id REGEXP '[^[:space:]]' AND agent_id != #{excludedAgentId}
    ) ranked
    WHERE agent_rank = 1
    ORDER BY created_at DESC, message_id ASC
    LIMIT #{limit}
) latest ON latest.message_id = message.message_id
ORDER BY message.created_at DESC, message.message_id ASC

mapper.insert:
INSERT INTO agent_context_message_receipt (user_id, thread_id, agent_id, message_id, content_version, summarized_version) SELECT #{userId}, #{threadId}, #{agentId}, delivered.message_id, delivered.content_version, CASE WHEN #{summarized} THEN delivered.content_version ELSE NULL END FROM (
SELECT #{receipt.messageId} AS message_id, #{receipt.contentVersion} AS content_version
) delivered JOIN chat_message message ON message.message_id = delivered.message_id AND message.thread_id = #{threadId} JOIN chat_thread thread ON thread.thread_id = message.thread_id AND thread.user_id = #{userId} ON DUPLICATE KEY UPDATE content_version = VALUES(content_version), summarized_version = COALESCE(VALUES(summarized_version), summarized_version), acknowledged_at = CURRENT_TIMESTAMP(3)

mapper.select:
SELECT message_id, summarized_version FROM agent_context_message_receipt
WHERE user_id = #{userId} AND thread_id = #{threadId} AND agent_id = #{agentId}
  AND summarized_version IS NOT NULL
